import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="3mo",progress=False,auto_adjust=True); close=data["Close"]; print("\n".join(f"{t}: {float(close[t].iloc[-1]):.2f} | Variation 5j: {((float(close[t].iloc[-1])/float(close[t].iloc[-6])-1)*100):+.2f}% | MM20: {float(close[t].tail(20).mean()):.2f} | Signal: {'ACHAT' if ((float(close[t].iloc[-1])/float(close[t].iloc[-6])-1)*100)>3 and float(close[t].iloc[-1])>float(close[t].tail(20).mean()) else 'SURVEILLANCE' if float(close[t].iloc[-1])>float(close[t].tail(20).mean()) else 'AUCUN SIGNAL'}" for t in tickers if t in close.columns and close[t].dropna().shape[0]>=20))
